export const generateGraphData = (fileInfoList = [], symbolsList = [], relationshipsList = []) => {
  const nodesMap = new Map();
  const edgesMap = new Map();

  const addNode = (node) => {
    if (node && node.id && !nodesMap.has(node.id)) {
      nodesMap.set(node.id, node);
    }
  };

  const addEdge = (edge) => {
    if (edge && edge.id && !edgesMap.has(edge.id)) {
      edgesMap.set(edge.id, edge);
    }
  };

  // 1. Root Repository Node
  addNode({
    id: 'repository',
    type: 'repository',
    name: 'repository',
    parent_id: null,
  });

  // 2. Build Directory & File Hierarchy
  for (const fileItem of fileInfoList) {
    const rawPath = typeof fileItem === 'string' ? fileItem : (fileItem.path || fileItem.file);
    if (!rawPath) continue;

    const normalizedPath = normPath(rawPath);
    const pathParts = normalizedPath.split('/');

    let currentParentId = 'repository';
    let currentPathAccumulator = '';

    // Process folders
    for (let i = 0; i < pathParts.length - 1; i++) {
      const folderName = pathParts[i];
      currentPathAccumulator = currentPathAccumulator
        ? `${currentPathAccumulator}/${folderName}`
        : folderName;

      const folderId = currentPathAccumulator;

      addNode({
        id: folderId,
        type: 'folder',
        name: folderName,
        parent_id: currentParentId,
      });

      addEdge({
        id: `contains:${currentParentId}:${folderId}`,
        type: 'CONTAINS',
        source: currentParentId,
        target: folderId,
      });

      currentParentId = folderId;
    }

    // Process file node
    const fileName = pathParts[pathParts.length - 1];
    const fileId = normalizedPath;

    addNode({
      id: fileId,
      type: 'file',
      name: fileName,
      parent_id: currentParentId,
    });

    addEdge({
      id: `contains:${currentParentId}:${fileId}`,
      type: 'CONTAINS',
      source: currentParentId,
      target: fileId,
    });
  }

  // Map to resolve symbol names to full IDs per file
  const symbolLookupByFileAndName = new Map();

  // 3. Process Code Symbols
  for (const symbol of symbolsList) {
    const symId = normPath(symbol.id);
    const filePath = normPath(symbol.file || symbol.path);
    
    // Fallback: If file node didn't exist in fileInfo, add it
    if (filePath && !nodesMap.has(filePath)) {
      addNode({
        id: filePath,
        type: 'file',
        name: filePath.split('/').pop(),
        parent_id: 'repository',
      });
      addEdge({
        id: `contains:repository:${filePath}`,
        type: 'CONTAINS',
        source: 'repository',
        target: filePath,
      });
    }

    // Index symbol for parent lookup resolution
    if (filePath && symbol.name) {
      const key = `${filePath}:${symbol.name}`;
      symbolLookupByFileAndName.set(key, symId);
    }

    addNode({
      id: symId,
      type: symbol.type,
      name: symbol.name,
      path: filePath,
      parent_id: symbol.parent ? normPath(symbol.parent) : filePath,
    });
  }

  // Create CONTAINS edges for symbols after indexing
  for (const symbol of symbolsList) {
    const symId = normPath(symbol.id);
    const filePath = normPath(symbol.file || symbol.path);
    let rawParent = symbol.parent ? normPath(symbol.parent) : null;

    let resolvedParentId = filePath; // Default parent is the file node

    if (rawParent) {
      if (nodesMap.has(rawParent)) {
        resolvedParentId = rawParent;
      } else {
        // Try looking up parent symbol by file + parent name
        const parentLookupKey = `${filePath}:${rawParent}`;
        if (symbolLookupByFileAndName.has(parentLookupKey)) {
          resolvedParentId = symbolLookupByFileAndName.get(parentLookupKey);
        }
      }
    }

    // Update parent_id on the node if resolved
    const node = nodesMap.get(symId);
    if (node) {
      node.parent_id = resolvedParentId;
    }

    if (resolvedParentId) {
      addEdge({
        id: `contains:${resolvedParentId}:${symId}`,
        type: 'CONTAINS',
        source: resolvedParentId,
        target: symId,
      });
    }
  }

  // 4. Process Semantic Relationships
  for (const rel of relationshipsList) {
    const sourceId = normPath(rel.source);
    
    // Target is valid only if resolved with a target_symbol_id
    const targetSymbolId = rel.target_symbol_id ? normPath(rel.target_symbol_id) : null;
    const isResolved = Boolean(rel.resolved && targetSymbolId);
    
    const targetId = isResolved ? targetSymbolId : null;
    const targetName = rel.target || rel.target_name || 'unknown';
    const edgeTypeLower = (rel.type || 'rel').toLowerCase();

    let edgeId;
    if (targetId) {
      edgeId = `${edgeTypeLower}:${sourceId}:${targetId}`;
    } else {
      edgeId = `${edgeTypeLower}:${sourceId}:unresolved:${targetName}`;
    }

    const edgeObj = {
      id: edgeId,
      type: rel.type,
      source: sourceId,
      target: targetId,
      resolved: isResolved,
      revealed: rel.revealed ?? false,
    };

    if (!targetId) {
      edgeObj.target_name = targetName;
    }

    addEdge(edgeObj);
  }

  return {
    nodes: Array.from(nodesMap.values()),
    edges: Array.from(edgesMap.values()),
  };
};

export const buildAndSaveGraph = (analysisDir) => {
  const readJson = (fileName) => {
    const filePath = path.join(analysisDir, fileName);
    if (fs.existsSync(filePath)) {
      return JSON.parse(fs.readFileSync(filePath, 'utf8'));
    }
    return null;
  };

  const fileInfoData = readJson('analysis.json') || readJson('fileinfo.json') || [];
  const fileInfo = Array.isArray(fileInfoData) ? fileInfoData : (fileInfoData.files || fileInfoData.file_info || []);

  const symbolsData = readJson('symbols.json') || readJson('basic_structure.json') || [];
  const symbols = Array.isArray(symbolsData) ? symbolsData : (symbolsData.symbols || []);

  const relData = readJson('relationships.json');
  const relationships = Array.isArray(relData) ? relData : (relData?.relationships || []);

  const graphData = generateGraphData(fileInfo, symbols, relationships);

  const outputPath = path.join(analysisDir, 'graph.json');
  fs.writeFileSync(outputPath, JSON.stringify(graphData, null, 2));

  console.log(`Successfully generated ${outputPath} with ${graphData.nodes.length} nodes and ${graphData.edges.length} edges.`);
  return outputPath;
};

export const validateGraph = (analysisDir) => {
  const readJson = (fileName) => {
    const filePath = path.join(analysisDir, fileName);
    return fs.existsSync(filePath) ? JSON.parse(fs.readFileSync(filePath, 'utf8')) : null;
  };

  const graph = readJson('graph.json');
  const relData = readJson('relationships.json');

  if (!graph) {
    console.error(`❌ Validation failed: graph.json not found in ${analysisDir}`);
    return false;
  }

  const { nodes = [], edges = [] } = graph;
  const errors = [];

  const nodeIds = new Set();
  const edgeIds = new Set();
  const containsEdgeSet = new Set();
  const semanticEdgeSet = new Set();

  // 1. Node ID Uniqueness
  for (const node of nodes) {
    if (!node.id) {
      errors.push(`Node missing ID property: ${JSON.stringify(node)}`);
      continue;
    }
    if (nodeIds.has(node.id)) {
      errors.push(`Duplicate Node ID: "${node.id}"`);
    } else {
      nodeIds.add(node.id);
    }
  }

  // 2. Edge ID Uniqueness, Source/Target Existence, and Duplicate Checks
  for (const edge of edges) {
    if (!edge.id) {
      errors.push(`Edge missing ID property: ${JSON.stringify(edge)}`);
      continue;
    }

    // Check edge ID uniqueness
    if (edgeIds.has(edge.id)) {
      errors.push(`Duplicate Edge ID: "${edge.id}"`);
    } else {
      edgeIds.add(edge.id);
    }

    // Check edge source exists as a node
    if (!nodeIds.has(edge.source)) {
      errors.push(`Edge "${edge.id}" source does not exist as a node: "${edge.source}"`);
    }

    // Check edge target exists as a node (unless unresolved external relationship where target = null)
    if (edge.target !== null && !nodeIds.has(edge.target)) {
      errors.push(`Edge "${edge.id}" target does not exist as a node: "${edge.target}"`);
    }

    // Duplicate CONTAINS and Semantic Edge checks
    if (edge.type === 'CONTAINS') {
      const pairKey = `${edge.source} ->${edge.target}`;
      if (containsEdgeSet.has(pairKey)) {
        errors.push(`Duplicate CONTAINS edge detected: ${pairKey}`);
      }
      containsEdgeSet.add(pairKey);
    } else {
      const key = `${edge.type}:${edge.source}->${edge.target}:${edge.target_name || ''}`;
      if (semanticEdgeSet.has(key)) {
        errors.push(`Duplicate semantic edge detected (${edge.type}):${key}`);
      }
      semanticEdgeSet.add(key);
    }
  }

  // 3. Hierarchy & Parent Validation
  for (const node of nodes) {
    if (node.id === 'repository') continue;

    // Check file nodes parent is correct folder (or root repository)
    if (node.type === 'file') {
      const pathParts = node.id.split('/');
      const expectedParent = pathParts.length > 1 
        ? pathParts.slice(0, -1).join('/') 
        : 'repository';

      if (node.parent_id !== expectedParent) {
        errors.push(`File node "${node.id}" parent_id is "${node.parent_id}", expected "${expectedParent}"`);
      }
    }

    // Check symbol parent_id exists in nodes
    if (['class', 'function', 'method', 'variable'].includes(node.type)) {
      if (!node.parent_id) {
        errors.push(`Symbol node "${node.id}" is missing parent_id`);
      } else if (!nodeIds.has(node.parent_id)) {
        errors.push(`Symbol node "${node.id}" points to non-existent parent_id "${node.parent_id}"`);
      }
    }

    // Check CONTAINS edge agreement with node parent_id
    if (node.parent_id) {
      const expectedContainsPair = `${node.parent_id} ->${node.id}`;
      if (!containsEdgeSet.has(expectedContainsPair)) {
        errors.push(`Missing CONTAINS edge from parent "${node.parent_id}" to child "${node.id}"`);
      }
    }
  }

  // 4. Presence of relationships.json entries in graph.json
  if (relData) {
    const rawRels = Array.isArray(relData) ? relData : (relData.relationships || []);
    for (const rel of rawRels) {
      const sourceId = normPath(rel.source);
      const targetId = (rel.resolved && rel.target_symbol_id) ? normPath(rel.target_symbol_id) : null;
      const targetName = rel.target || rel.target_name;

      const found = edges.some((e) => 
        e.type === rel.type &&
        e.source === sourceId &&
        e.target === targetId &&
        (targetId !== null || e.target_name === targetName)
      );

      if (!found) {
        errors.push(`Relationship from relationships.json not found in graph.json: type="${rel.type}", source="${sourceId}", target="${targetId || targetName}"`);
      }
    }
  }

  // Report Validation Results
  console.log(`\n========================================`);
  console.log(`       Graph Validation Report          `);
  console.log(`========================================`);
  console.log(`Nodes checked : ${nodes.length}`);
  console.log(`Edges checked : ${edges.length}`);

  if (errors.length === 0) {
    console.log(`\n✅ SUCCESS: All graph validation checks passed cleanly!\n`);
    return true;
  } else {
    console.error(`\n❌ FAILED: Found ${errors.length} validation errors:\n`);
    errors.forEach((err, idx) => console.error(`  ${idx + 1}.${err}`));
    console.log(``);
    return false;
  }
};

