function createTrunkPath(
  sourceX,
  sourceY,
  targetX,
  targetY,
  trunkX,
  r = 8,
  offset = 20,
) {
  if (!trunkX) {
    return `M ${sourceX} ${sourceY} L ${sourceX} ${targetY} L ${targetX} ${targetY}`;
  }

  const cornerY = sourceY + offset;

  // Directions (-1 or +1)
  const dirX1 = trunkX > sourceX ? 1 : -1;
  const dirX2 = targetX > trunkX ? 1 : -1;
  const dirY = targetY > cornerY ? 1 : -1;

  // Corner radii bounds
  const r1 = Math.min(
    r,
    Math.abs(trunkX - sourceX) / 2,
    Math.abs(cornerY - sourceY),
  );
  const r2 = Math.min(
    r,
    Math.abs(trunkX - sourceX) / 2,
    Math.abs(targetY - cornerY) / 2,
  );
  const r3 = Math.min(
    r,
    Math.abs(targetX - trunkX) / 2,
    Math.abs(targetY - cornerY) / 2,
  );

  return [
    `M ${sourceX} ${sourceY}`,
    `L ${sourceX} ${cornerY - r1 * dirY}`,
    `Q ${sourceX} ${cornerY}, ${sourceX + r1 * dirX1} ${cornerY}`,
    `L ${trunkX - r2 * dirX1} ${cornerY}`,
    `Q ${trunkX} ${cornerY}, ${trunkX} ${cornerY + r2 * dirY}`,
    `L ${trunkX} ${targetY - r3 * dirY}`,
    `Q ${trunkX} ${targetY}, ${trunkX + r3 * dirX2} ${targetY}`,
    `L ${targetX} ${targetY}`,
  ].join(" ");
}

export default function TrunkEdge({
  id,
  sourceX,
  sourceY,
  targetX,
  targetY,
  style,
  markerEnd,
  data,
}) {
  const edgePath = createTrunkPath(
    sourceX,
    sourceY,
    targetX,
    targetY,
    data?.trunkX,
  );

  return (
    <BaseEdge
      id={id}
      path={edgePath}
      style={style || { stroke: "#cccccc", strokeWidth: 1.5 }}
      markerEnd={markerEnd}
    />
  );
}

const LIMITS = {
  MAX_FILE_COUNT: 10000,
  MAX_REPOSITORY_SIZE: 100 * 1024 * 1024, // 100 MB
  MAX_FILE_SIZE: 1 * 1024 * 1024,        // 1 MB
};

const getSupportedExtensions = () => {
  const extEnv = process.env.SUPPORTED_EXTENSIONS || '.js,.ts,.jsx,.tsx,.py,.json';
  return new Set(extEnv.split(',').map((ext) => ext.trim().toLowerCase()));
};

const scanAndAnalyzeRepo = (dirPath) => {
  const supportedExts = getSupportedExtensions();
  const fileResults = [];
  const ignoredDirs = new Set(['.git', 'node_modules', 'dist', 'build', 'temp_data']);
  let totalRepoSize = 0;

  const walkDirectory = (currentDir) => {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true });

    for (const entry of entries) {
      if (fileResults.length >= LIMITS.MAX_FILE_COUNT) {
        console.warn(`[Warning] Reached MAX_FILE_COUNT limit (${LIMITS.MAX_FILE_COUNT}). Stopping scan.`);
        return;
      }

      const fullPath = path.join(currentDir, entry.name);

      if (entry.isDirectory()) {
        if (ignoredDirs.has(entry.name)) {
          continue;
        }
        walkDirectory(fullPath);
      } else if (entry.isFile()) {
        const stats = fs.statSync(fullPath);
        totalRepoSize += stats.size;

        if (totalRepoSize > LIMITS.MAX_REPOSITORY_SIZE) {
          throw new Error(`Repository total size exceeds limit of ${LIMITS.MAX_REPOSITORY_SIZE / (1024 * 1024)}MB.`);
        }

        const ext = path.extname(entry.name).toLowerCase();

        if (supportedExts.has(ext)) {
          let lineCount = 0;

          if (stats.size <= LIMITS.MAX_FILE_SIZE) {
            try {
              const content = fs.readFileSync(fullPath, 'utf8');
              lineCount = content.split('\n').length;
            } catch {
              lineCount = 0;
            }
          }

          const relativePath = path.relative(dirPath, fullPath).replace(/\\/g, '/');

          fileResults.push({
            path: relativePath,
            name: entry.name,
            extension: ext,
            language: LANGUAGE_MAP[ext] || 'unknown',
            size: stats.size,
            lineCount: lineCount,
            truncated: stats.size > LIMITS.MAX_FILE_SIZE,
          });
        }
      }
    }
  };

  walkDirectory(dirPath);
  return fileResults;
};

